def rot_a_to_b(u, v):
    u = u/np.linalg.norm(u); v = v/np.linalg.norm(v); c = np.cross(u, v); s = np.linalg.norm(c); cth = u @ v
    if s < 1e-9: return np.eye(3)
    k = c/s; K = np.array([[0,-k[2],k[1]],[k[2],0,-k[0]],[-k[1],k[0],0]])
