def measure_cup(z_lo, z_hi, guess_xy, rad=0.02, verbose=True):
    xyz, rgb, ci = ep.cloud(cams=["left","right"], stride=1)
    m = (np.hypot(xyz[:,0]-guess_xy[0], xyz[:,1]-guess_xy[1]) < rad) & (xyz[:,2] > z_lo) & (xyz[:,2] < z_hi)
    P = xyz[m]; zs, cs = [], []
    for z0 in np.arange(z_lo, z_hi, 0.005):
        mm = (P[:,2]>=z0)&(P[:,2]<z0+0.005)
        if mm.sum() >= 8:
            cx, cy, r = rh.fit_circle(P[mm,:2])
            if 0.0085 < r < 0.0105: zs.append(z0+0.0025); cs.append((cx, cy, r, mm.sum()))
    zs = np.array(zs); cs = np.array(cs)
    if len(zs) < 3:
        print("too few slices", len(zs), "pts", len(P)); return None
    A = np.c_[zs, np.ones_like(zs)]
    kx_ = np.linalg.lstsq(A, cs[:,0], rcond=None)[0]; ky_ = np.linalg.lstsq(A, cs[:,1], rcond=None)[0]
    res = np.hypot(A@kx_ - cs[:,0], A@ky_ - cs[:,1])
